'use strict';
const $=s=>document.querySelector(s), E=R360.esc, money=R360.money;
let user,guestProfile,moduleName='dashboard',page=1,lookups={},rows=[],charts=[],requestVersion=0;
let routeFilters=new URLSearchParams(),dashboardRequest=0,refreshBusy=false;
function chartPalette(){return document.documentElement.dataset.theme==='dark'?{text:'#b7cac7',grid:'#2e454b',bar:'#50b998',vacant:'#2b4146',donut:['#348c70','#2b4146','#ca895b'],lines:['#67d1aa','#e1b866','#6fc6d1','#d18bd1']}:{text:'#52665d',grid:'#eff2eb',bar:'#6d9166',vacant:'#e9efdf',donut:['#356a50','#e9efdf','#d6a36b'],lines:['#386d50','#b39453','#779da0','#9b5f91']};}
function updateChartTheme(){
 const palette=chartPalette();Chart.defaults.color=palette.text;Chart.defaults.borderColor=palette.grid;
 charts.forEach(chart=>{
  Object.values(chart.options.scales||{}).forEach(scale=>{if(scale.ticks)scale.ticks.color=palette.text;if(scale.title)scale.title.color=palette.text;if(scale.grid&&scale.grid.display!==false)scale.grid.color=palette.grid;});
  chart.data.datasets.forEach((dataset,index)=>{if(chart.canvas.id==='reservationChart')dataset.backgroundColor=palette.bar;if(chart.canvas.id==='occupancyChart')dataset.backgroundColor=palette.donut;if(chart.canvas.id==='temperatureChart')dataset.borderColor=palette.lines[index%palette.lines.length];});
  chart.update('none');
 });
}
window.addEventListener('resort360:themechange',updateChartTheme);
updateChartTheme();
function facilityDetailsPayload(facility){
 return E(JSON.stringify({name:facility.name,type:facility.type,capacity:facility.capacity,nightly_rate:facility.nightly_rate,description:facility.description,image_path:facility.image_path}));
}
function facilityPhoto(facility,size='preview'){
 if(!facility?.image_path)return '';
 const alt=`${facility.name} photo`;
 const opensDetails=size==='card';
 const detailData=opensDetails?` data-facility-details="${facilityDetailsPayload(facility)}"`:'';
 return `<button type="button" class="facility-photo-trigger facility-photo-trigger-${size}" data-photo-id="${E(facility.id)}" data-photo-src="${E(facility.image_path)}" data-photo-alt="${E(alt)}"${detailData} aria-label="${E(opensDetails?`View ${facility.name} details`:`Enlarge ${alt}`)}" aria-haspopup="dialog" title="${opensDetails?'View room details':'View larger photo'}"><img class="facility-photo facility-photo-${size}" src="${E(facility.image_path)}" alt="${E(alt)}" loading="lazy" decoding="async"><span class="facility-photo-zoom" aria-hidden="true"><i class="bi bi-arrows-fullscreen"></i></span></button>`;
}
function facilityDetails(description){
 const groups=[{title:'Room Inclusions',items:[]},{title:'Details',items:[]}],other=[];
 let section=-1,highlight='';
 for(const item of String(description||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean)){
  if(/^room inclusions\s*:?$/i.test(item)){section=0;continue;}
  if(/^details\s*:?$/i.test(item)){section=1;continue;}
  if(/^highlight\s*:?$/i.test(item)){section=2;continue;}
  if(section===0||section===1)groups[section].items.push(item);
  else if(section===2)highlight=highlight?`${highlight} ${item}`:item;
  else other.push(item);
 }
 const sections=groups.filter(group=>group.items.length).map(group=>`<section class="facility-details-section"><h3>${group.title}</h3><ul>${group.items.map(item=>`<li>${E(item)}</li>`).join('')}</ul></section>`);
 if(other.length)sections.unshift(`<section class="facility-details-section"><h3>Inclusions and details</h3><ul>${other.map(item=>`<li>${E(item)}</li>`).join('')}</ul></section>`);
 return `<div class="facility-details">${sections.join('')||'<p class="facility-details-empty">Inclusions and details have not been added yet.</p>'}${highlight?`<p class="facility-highlight">${E(highlight)}</p>`:''}</div>`;
}
function facilityDetailsButton(facility){
 return `<button type="button" class="btn btn-outline-secondary facility-details-button" data-facility-details="${facilityDetailsPayload(facility)}">View inclusions</button>`;
}
function showFacilityDetails(facility){
 const image=facility.image_path?`<img class="facility-details-image" src="${E(facility.image_path)}" alt="${E(facility.name)}">`:'';
 const summary=`<p class="facility-details-summary">${E(R360.label(facility.type))} · Up to ${E(facility.capacity)} guests · ${E(money(facility.nightly_rate))} / night</p>`;
 return Swal.fire({title:E(facility.name),html:`${image}${summary}${facilityDetails(facility.description)}`,confirmButtonText:'Close',confirmButtonColor:'#28664f',customClass:{popup:'facility-details-popup'}});
}
function openFacilityDetails(payload){
 Promise.resolve().then(()=>showFacilityDetails(JSON.parse(payload))).catch(R360.error);
}
document.addEventListener('click',event=>{
 const detailsTrigger=event.target.closest('[data-facility-details]');
 if(detailsTrigger){openFacilityDetails(detailsTrigger.dataset.facilityDetails);return;}
 const roomCard=event.target.closest('[data-open-facility]');
 if(roomCard&&!event.target.closest('button,a,input,select,textarea')){openFacilityDetails(roomCard.dataset.openFacility);return;}
 const trigger=event.target.closest('[data-photo-id]');if(!trigger)return;
 const photo={src:trigger.dataset.photoSrc,alt:trigger.dataset.photoAlt};if(!photo.src)return;
 const viewer=document.createElement('dialog');viewer.className='facility-photo-viewer';viewer.setAttribute('aria-labelledby','facilityPhotoTitle');
 viewer.innerHTML=`<div class="facility-photo-viewer-header"><h2 id="facilityPhotoTitle">${E(photo.alt)}</h2><button type="button" class="btn-close" aria-label="Close photo" autofocus></button></div><img class="facility-photo-full" src="${E(photo.src)}" alt="${E(photo.alt)}"><p class="facility-photo-viewer-note">Press Esc or tap outside the image viewer to close.</p>`;
 // Keep focus within an open reservation/details modal while using the native top layer.
 (document.querySelector('.modal.show')||document.body).append(viewer);
 viewer.querySelector('.btn-close').onclick=()=>viewer.close();
 viewer.addEventListener('keydown',e=>{if(e.key==='Escape')e.stopPropagation();});
 viewer.addEventListener('click',e=>{if(e.target!==viewer)return;const bounds=viewer.getBoundingClientRect();if(e.clientX<bounds.left||e.clientX>bounds.right||e.clientY<bounds.top||e.clientY>bounds.bottom)viewer.close();});
 viewer.addEventListener('close',()=>{viewer.remove();if(trigger.isConnected)trigger.focus({preventScroll:true});},{once:true});
 viewer.showModal();
});
const config={
 cash_requests:{title:'Cash payments',subtitle:'Pay in cash at reception. View payment slips and receipts here.',icon:'receipt',add:'Generate payment slip',columns:[['reference','Slip / receipt'],['booking','Booking'],['guest','Guest'],['amount','Cash amount'],['status','Status'],['created_at','Generated']],statuses:['pending','paid','cancelled','voided'],sorts:['reference','amount','created_at']},
 reservations:{title:'Reservations',subtitle:'Every arrival, every stay. Keep your bookings in view.',icon:'calendar2-week',add:'New reservation',columns:[['reference','Booking'],['guest','Guest'],['facility','Room / cottage'],['arrival','Arrival'],['departure','Departure'],['total','Total'],['balance','Balance'],['status','Status']],statuses:['pending','confirmed','checked_in','checked_out','cancelled','rejected'],sorts:['reference','arrival','departure','total','status','created_at']},
 guests:{title:'Guests',subtitle:'The people behind every great stay.',icon:'people',add:'Add guest',columns:[['name','Guest'],['email','Email'],['phone','Phone'],['address','Address']],archive:true,sorts:['name','email','created_at']},
 facilities:{title:'Rooms & cottages',subtitle:'Your spaces, availability and accommodation details.',icon:'door-open',add:'Add facility',columns:[['name','Space'],['type','Type'],['capacity','Capacity'],['nightly_rate','Nightly rate'],['status','Availability'],['occupied','Checked in']],archive:true,statuses:['available','maintenance'],sorts:['name','type','capacity','nightly_rate','status']},
 payments:{title:'Payment records',subtitle:'Recorded receipts and clear balances. No online charges.',icon:'credit-card',add:'Record payment',columns:[['booking','Booking'],['guest','Guest'],['amount','Amount'],['method','Method'],['reference','Reference'],['status','Status'],['created_at','Recorded']],statuses:['recorded','voided'],sorts:['amount','method','created_at']},
 maintenance:{title:'Maintenance',subtitle:'Keep every space ready for a better guest experience.',icon:'tools',add:'Report an issue',columns:[['title','Issue'],['facility','Facility'],['priority','Priority'],['assignee','Assigned to'],['status','Status']],statuses:['open','in_progress','completed','cancelled'],sorts:['title','priority','status','created_at']},
 devices:{title:'Facility monitoring',subtitle:'Live temperature visibility, with clear connection status.',icon:'activity',add:'Add device',columns:[['name','Device'],['facility','Facility'],['temperature','Temperature °C'],['status','Connection'],['last_seen','Last received']],sorts:['name','last_seen','created_at']},
 readings:{title:'Temperature history',subtitle:'Readings received from your connected ESP32 devices.',icon:'thermometer-half',columns:[['device','Device'],['facility','Facility'],['temperature','Temperature °C'],['sample_id','Sample'],['received_at','Received']],sorts:['temperature','received_at']},
 users:{title:'Team & accounts',subtitle:'Manage access for the people who make your resort work.',icon:'person-gear',add:'Create account',columns:[['name','Name'],['email','Email'],['role','Role'],['status','Account'],['created_at','Created']],statuses:['active','inactive'],sorts:['name','email','created_at']},
 audit:{title:'Activity log',subtitle:'A permanent history of important account and resort changes.',icon:'clock-history',columns:[['actor','User'],['action','Activity'],['entity','Module'],['entity_id','Record'],['details','Details'],['created_at','Time']],sorts:['action','entity','created_at']},
 notifications:{title:'Notifications',subtitle:'Updates that need your attention.',icon:'bell',columns:[['message','Update'],['status','Status'],['created_at','Received']],statuses:['unread','read'],sorts:['created_at']}
};
const can=p=>user.permissions.includes(p);
const canWrite=m=>m==='reservations'?(user.role==='guest'||can('reservations.manage')):m==='guests'?can('guests.manage'):m==='facilities'?can('facilities.manage'):['payments','cash_requests'].includes(m)?can('payments.manage'):m==='maintenance'?can('maintenance.manage'):m==='devices'?can('devices.manage'):m==='users'?can('users.manage'):false;
function titleBlock(title,subtitle,actions=''){return `<div class="page-heading"><div><span class="eyebrow">MNB BEACH RESORT</span><h1>${E(title)}</h1><p>${E(subtitle)}</p></div><div class="mobile-toolbar">${actions}</div></div>`;}
function empty(message='No records yet.',detail='Your records will appear here when they are added.'){return `<div class="empty-state"><i class="bi bi-inbox"></i><h3>${E(message)}</h3><p>${E(detail)}</p></div>`;}
function cell(key,value){if(['status','priority','role','payment_status'].includes(key))return R360.badge(value);if(['total','paid','balance','amount','nightly_rate'].includes(key))return E(money(value));if(key==='occupied')return value?'Yes':'No';return E(value===null||value===''?'—':value);}
function tableHtml(list,columns,actions=false,sortable=false){if(!list.length)return empty('Nothing to show yet.','Try adjusting your filters, or add your first record.');return `<div class="table-responsive"><table class="table align-middle"><thead><tr>${columns.map(([key,label])=>`<th>${sortable&&(config[moduleName]?.sorts||[]).includes(key)?`<button data-sort="${key}">${E(label)} <i class="bi bi-arrow-down-up"></i></button>`:E(label)}</th>`).join('')}${actions?'<th class="row-actions text-end">Actions</th>':''}</tr></thead><tbody>${list.map(r=>`<tr>${columns.map(([key])=>`<td>${key==='name'&&moduleName==='facilities'?`<div class="facility-name-cell">${facilityPhoto(r,'thumb')}<span>${cell(key,r[key])}</span></div>`:cell(key,r[key])}</td>`).join('')}${actions?`<td class="row-actions text-end text-nowrap">${actionsHtml(r)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function facilityCards(items){const spaces=items.filter(r=>['room','cottage'].includes(r.type));return spaces.length?`<div class="facility-gallery-grid">${spaces.map(r=>`<article class="facility-gallery-card" data-open-facility="${facilityDetailsPayload(r)}">${facilityPhoto(r,'card')}<div class="facility-gallery-info"><div class="facility-gallery-heading"><h2>${E(r.name)}</h2>${R360.badge(r.status)}</div><p>${E(R360.label(r.type))} · Up to ${E(r.capacity)} guests</p><strong>${E(money(r.nightly_rate))}<small> / night</small></strong>${facilityDetailsButton(r)}</div></article>`).join('')}</div>`:'';}
function actionsHtml(r){let html=`<button class="btn btn-light" data-action="view" data-id="${r.id}" aria-label="View record ${r.id}"><i class="bi bi-eye"></i></button> `;
 if(canWrite(moduleName)&&!r.archived_at&&!['payments','cash_requests'].includes(moduleName)&&(moduleName!=='reservations'||r.status==='pending'))html+=`<button class="btn btn-light" data-action="edit" data-id="${r.id}" aria-label="Edit record ${r.id}"><i class="bi bi-pencil"></i></button> `;
 if(moduleName==='reservations'){const statuses=user.role==='guest'?(['pending','confirmed'].includes(r.status)?['cancelled']:[]):({pending:['confirmed','rejected','cancelled'],confirmed:['checked_in','cancelled'],checked_in:['checked_out']}[r.status]||[]);const canConfirm=r.status==='pending'&&user.role!=='guest'&&can('reservations.manage');if(canConfirm)html+=`<button class="btn btn-success" data-action="status" data-status="confirmed" data-id="${r.id}" aria-label="Confirm reservation ${r.id}">Confirm</button> `;const menuStatuses=canConfirm?statuses.filter(s=>s!=='confirmed'):statuses;if(menuStatuses.length)html+=`<div class="dropdown d-inline-block"><button class="btn btn-light dropdown-toggle" data-bs-toggle="dropdown">Status</button><ul class="dropdown-menu">${menuStatuses.map(s=>`<li><button class="dropdown-item" data-action="status" data-status="${s}" data-id="${r.id}">${E(R360.label(s))}</button></li>`).join('')}</ul></div> `;}
 if(config[moduleName]?.archive&&canWrite(moduleName))html+=`<button class="btn btn-light" data-action="${r.archived_at?'restore':'archive'}" data-id="${r.id}" aria-label="${r.archived_at?'Restore':'Archive'} record"><i class="bi bi-${r.archived_at?'arrow-counterclockwise':'archive'}"></i></button>`;
 if(moduleName==='reservations'&&can('payments.manage')&&Number(r.balance)>0&&!['cancelled','rejected'].includes(r.status))html+=`<button class="btn btn-light" data-action="cash-slip" data-id="${r.id}">Payment slip</button> `;
 if(moduleName==='payments'&&can('payments.void')&&!r.voided_at)html+=`<button class="btn btn-light" data-action="void" data-id="${r.id}">Void</button>`;
 if(moduleName==='notifications'){const cashRef=r.message.match(/CASH-[A-F0-9]{12}/);if(cashRef)html+=`<a class="btn btn-light" href="#cash_requests?search=${encodeURIComponent(cashRef[0])}">Open cash payment</a> `;if(r.status==='unread')html+=`<button class="btn btn-light" data-action="read" data-id="${r.id}">Mark read</button> `;const ref=r.message.match(/R360-[A-F0-9]{10}/);if(ref&&(can('reservations.manage')||user.role==='guest'))html+=`<a class="btn btn-light" href="#reservations?search=${encodeURIComponent(ref[0])}">Open booking</a>`;}
 if(moduleName==='users'&&r.active)html+=`<button class="btn btn-light" data-action="reset" data-id="${r.id}">Reset</button>`;
 if(moduleName==='devices'&&can('devices.manage'))html+=`<button class="btn btn-light" data-action="key" data-id="${r.id}">New key</button>`;
 return html;
}
async function navigate(){
 const current=++requestVersion;const [route,query='']=location.hash.slice(1).split('?');moduleName=route||'dashboard';page=1;routeFilters=new URLSearchParams(query);
 charts.forEach(c=>c.destroy());charts=[];
 document.querySelectorAll('[data-module]').forEach(a=>a.classList.toggle('active',a.dataset.module===moduleName));
 bootstrap.Offcanvas.getInstance($('#sidebar'))?.hide();$('#crumb').textContent=config[moduleName]?.title||R360.label(moduleName==='dashboard'?'overview':moduleName);
 $('#workspace').innerHTML='<div class="loading-state"><div class="spinner-border text-success" role="status"><span class="visually-hidden">Loading</span></div></div>';
 try {if(moduleName==='dashboard')await dashboard(current);else if(moduleName==='profile')await profile(current);else if(moduleName==='reports'){if(!can('reports.read'))throw new Error('You do not have access to reports.');reportShell();await loadReport();}else if(config[moduleName]){moduleShell();await loadTable(current);}else throw new Error('Page not found.');}catch(error){if(current===requestVersion)$('#workspace').innerHTML=`<div class="alert alert-danger">${E(error.message)}</div>`;}
}
async function dashboard(version){
 const seq=++dashboardRequest,guest=user.role==='guest',staff=user.role==='staff';const [d,facilityData]=await Promise.all([R360.api('dashboard'),guest?R360.api('records','GET',null,{module:'facilities',per_page:50}):Promise.resolve(null)]);if(version!==requestVersion||seq!==dashboardRequest)return;charts.forEach(c=>c.destroy());charts=[];
 const stats=staff?[[d.facilities.total,'Bookable spaces','door-open','Rooms and cottages'],[d.occupied,'Currently occupied','house-check','Checked-in stays'],[d.maintenance,'Open maintenance','tools','Work awaiting completion'],[d.devices.filter(x=>x.status==='online').length,'Devices online','activity','Recent sensor connections']]:[[d.summary.reservations,guest?'Your reservations':'Total reservations','calendar2-week','All recorded reservations'],[d.summary.pending,'Awaiting confirmation','hourglass-split','Pending reservation requests'],[guest?d.summary.active:d.occupancy+(d.facilities.total?'%':''),guest?'Upcoming & active':'Current occupancy','door-open',guest?'Pending, confirmed and checked in':`${d.occupied} of ${d.facilities.total} units occupied`],[money(d.payments),guest?'Your recorded payments':'Recorded payments','wallet2','Valid payment records · all time']];
 $('#workspace').innerHTML=titleBlock('Overview','A clear view of your resort, all in one place.',guest||can('reservations.manage')?'<button class="btn btn-primary" data-new="reservations"><i class="bi bi-plus-lg me-2"></i>New reservation</button>':'')+`<div class="refresh-status"><span id="refreshStatus" role="status">Updated ${E(d.updated_at)} | Asia/Manila | refreshes every 30 seconds</span><button class="btn btn-light" id="dashboardRefresh" aria-label="Refresh overview"><i class="bi bi-arrow-clockwise"></i></button></div><section class="welcome-banner"><div><h2>Hello, ${E(user.name.split(' ')[0])}.</h2><p>${guest?'Your next getaway starts here. Find a space and make it yours.':staff?'A little care keeps every space ready. Here’s your day at a glance.':'Here’s what’s happening at MNB Beach Resort today.'}</p></div><div class="banner-illustration" aria-hidden="true"><i class="bi bi-brightness-high"></i><i class="bi bi-water"></i><i class="bi bi-house"></i></div></section><section class="stat-grid">${stats.map(([v,l,i,s],n)=>`<a class="stat-card stat-link ${n===0?'primary':''}" href="${staff?['#facilities','#facilities','#maintenance?status=open','#devices'][n]:['#reservations','#reservations?status=pending',guest?'#reservations':'#reservations?status=checked_in','#payments?status=recorded'][n]}"><div class="stat-label">${E(l)}<i class="bi bi-${i}"></i></div><div class="stat-value">${E(v)}</div><small>${E(s)}</small></a>`).join('')}</section>${operationsHtml(d.operations)}<div class="dashboard-columns"><section class="panel"><div class="panel-head"><div><h2>${staff?'Facility conditions':'Reservation activity'}</h2><p>${staff?'Most recent sensor observations':'Reservations by arrival month · rolling six months onward'}</p></div><span class="status-badge">${staff?'Monitoring':'Bookings'}</span></div><div class="panel-body">${staff?deviceCards(d.devices.slice(0,2)):d.series.length?'<div class="chart-box"><canvas id="reservationChart" aria-label="Reservations by month" role="img"></canvas></div>':empty('Your story starts here.','Reservation trends will appear after your first booking.')}</div></section><section class="panel"><div class="panel-head"><div><h2>${guest?'Your next steps':'Occupancy overview'}</h2><p>${guest?'Plan your time by the coast':'Occupied, vacant and maintenance units'}</p></div><i class="bi bi-three-dots"></i></div><div class="panel-body">${guest?'<div class="empty-state"><i class="bi bi-calendar2-heart"></i><h3>A stay to look forward to.</h3><p>Choose dates, check available rooms and cottages, then submit a request.</p><button class="btn btn-outline-secondary" data-new="reservations">Find your stay <i class="bi bi-arrow-right ms-2"></i></button></div>':'<div class="chart-box"><canvas id="occupancyChart" aria-label="Occupied and remaining units" role="img"></canvas></div><div class="occupancy-detail"><span><i class="legend-dot"></i>Occupied</span><span><i class="legend-dot pale"></i>Vacant</span><span><i class="legend-dot maintenance"></i>Maintenance</span></div><p class="text-muted small">Vacant units may have upcoming reservations. Check dates before booking.</p>'}</div></section></div><section class="panel mb-4"><div class="panel-head"><div><h2>${staff?'Recent maintenance':'Recent reservations'}</h2><p>${staff?'The latest facility work':'Your latest booking updates'}</p></div><a class="btn btn-outline-secondary" href="#${staff?'maintenance':'reservations'}">View all <i class="bi bi-arrow-up-right ms-2"></i></a></div>${tableHtml(d.recent,staff?config.maintenance.columns:[['reference','Booking'],['guest','Guest'],['facility','Space'],['arrival','Arrival'],['status','Status']])}</section>${d.notifications.length?`<section class="panel"><div class="panel-head"><h2>Needs your attention</h2><a href="#notifications">View updates →</a></div>${d.notifications.map(n=>`<div class="notification-row"><span><i class="bi bi-circle-fill text-success me-2 small"></i>${E(n.message)}</span><small>${E(n.created_at)}</small></div>`).join('')}</section>`:''}`;
 if(!staff&&d.series.length){const palette=chartPalette();charts.push(new Chart($('#reservationChart'),{type:'bar',data:{labels:d.series.map(x=>x.label),datasets:[{data:d.series.map(x=>x.value),backgroundColor:palette.bar,borderRadius:5,maxBarThickness:34}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0,color:palette.text},grid:{color:palette.grid}},x:{ticks:{color:palette.text},grid:{display:false}}}}}));}
 if(!guest){const palette=chartPalette();charts.push(new Chart($('#occupancyChart'),{type:'doughnut',data:{labels:['Occupied','Vacant','Maintenance'],datasets:[{data:[d.occupied,Math.max(0,d.facilities.total-d.occupied-d.facilities.maintenance),d.facilities.maintenance],backgroundColor:palette.donut,borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'76%',plugins:{legend:{display:false}}}}));}
 if(guest)$('#workspace .welcome-banner').insertAdjacentHTML('afterend',`<section class="panel mb-4"><div class="panel-head"><div><h2>Rooms &amp; cottages</h2><p>Tap a room or cottage to view its photo, inclusions and details.</p></div><button class="btn btn-outline-secondary" data-new="reservations">Check availability</button></div><div class="panel-body"><div class="facility-gallery">${facilityData.rows.length?facilityCards(facilityData.rows):empty('No rooms or cottages listed.','Please check back soon.')}</div></div></section>`);
 updateNotificationCount(d.unread_count);bindNew();$('#dashboardRefresh').onclick=()=>refreshWorkspace();bindOperationActions();
}
function deviceCards(list){return list.length?list.map(d=>`<article class="device-card"><div class="d-flex justify-content-between"><i class="bi bi-thermometer-half"></i>${R360.badge(d.status)}</div><h3>${E(d.name)}</h3><p>${E(d.facility)}</p><div class="temperature">${d.temperature===null?'—':E(d.temperature)}<span> °C</span></div>${d.alert?'<div class="alert alert-warning py-2">Outside configured temperature range</div>':''}<p>Configured range ${E(d.min_temp)}–${E(d.max_temp)}°C</p><div class="reading-time">${d.last_seen?'Last received '+E(d.last_seen):'No reading received yet'}</div></article>`).join(''):empty('No connected devices.','Add a device and configure its key on your ESP32.');}
function manilaDate(offset=0){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const date=new Date(today+'T00:00:00Z');date.setUTCDate(date.getUTCDate()+offset);return date.toISOString().slice(0,10);}
function operationsHtml(operations){
 if(!operations?.arrivals)return '';
 const labels={arrivals:'Arrivals today',departures:'Departures today',overdue:'Overdue check-outs',outstanding:'Outstanding balances'};
 return `<section class="panel mb-4"><div class="panel-head"><div><h2>Today’s operations</h2><p>Asia/Manila · up to five bookings per queue</p></div><a href="#reservations?status=pending">Review pending requests</a></div><div class="operations-grid">${Object.entries(labels).map(([key,label])=>`<section class="operation-queue"><h3><a href="#reservations?operation=${key}">${label} <span class="status-badge">${operations[key].total}</span></a></h3>${operations[key].rows.map(r=>`<div class="operation-item"><a href="#reservations?search=${encodeURIComponent(r.reference)}">${E(r.reference)}</a><span>${E(r.guest)} · ${E(r.facility)}</span><small>${R360.label(r.status)} · Balance ${money(r.balance)}</small>${key==='arrivals'&&r.status==='confirmed'?`<button class="btn btn-light" data-operation="checked_in" data-id="${r.id}">Check in</button>`:['departures','overdue'].includes(key)?`<button class="btn btn-light" data-operation="checked_out" data-id="${r.id}" ${Number(r.balance)!==0?'disabled title="Settle the balance before check-out"':''}>Check out</button>`:''}${Number(r.balance)>0?`<button class="btn btn-light" data-payment="${r.id}">Record payment</button>`:''}</div>`).join('')||'<p class="text-muted small">No bookings in this queue.</p>'}</section>`).join('')}</div></section>`;
}
function bindOperationActions(){
 document.querySelectorAll('[data-payment]').forEach(b=>b.onclick=()=>openForm('payments',null,{reservation_id:b.dataset.payment}).catch(R360.error));
 document.querySelectorAll('[data-operation]').forEach(b=>b.onclick=async()=>{try{if(!await R360.confirm(`Mark reservation ${R360.label(b.dataset.operation).toLowerCase()}?`))return;b.disabled=true;await R360.api('records','PATCH',{action:'status',status:b.dataset.operation},{module:'reservations',id:b.dataset.id});R360.toast('Reservation updated.');if(moduleName==='dashboard')await dashboard(requestVersion);}catch(e){R360.error(e);}finally{b.disabled=false;}});
}
async function refreshWorkspace(){
 if(refreshBusy||document.hidden||$('#recordModal.show')||document.querySelector('.swal2-container'))return;
 refreshBusy=true;const version=requestVersion;
 try{
  const n=await R360.api('records','GET',null,{module:'notifications',status:'unread',per_page:1});updateNotificationCount(n.total);
  if(version!==requestVersion)return;
  if(moduleName==='dashboard')await dashboard(version);
  else if(['devices','readings','cash_requests'].includes(moduleName))await loadTable(version);
  $('#connectionNotice')?.remove();
 }catch(e){if(version===requestVersion){if(!$('#connectionNotice'))$('#workspace').insertAdjacentHTML('afterbegin','<div id="connectionNotice" class="alert alert-warning" role="status"></div>');$('#connectionNotice').textContent='Refresh failed. Displayed data may be outdated. '+e.message;}}
 finally{refreshBusy=false;}
}
async function loadTrend(q,version,seq){
 charts.forEach(c=>c.destroy());charts=[];$('#trendStatus').textContent='Loading trend…';
 try{
  const d=await R360.api('trend','GET',null,q);if(version!==requestVersion||seq!==tableRequest)return;
  const buckets=[],ids=[...new Set(d.rows.map(r=>r.device_id))];
  for(let time=Date.parse(d.from+'T00:00:00Z'),end=Date.parse(d.to+'T23:00:00Z');time<=end;time+=3600000)buckets.push(new Date(time).toISOString().slice(0,19).replace('T',' '));
  const datasets=ids.map((id,i)=>{const records=d.rows.filter(r=>r.device_id===id),byTime=new Map(records.map(r=>[r.bucket,r])),device=records[0];return {label:`${device.device} · ${device.facility} (#${id})`,data:buckets.map(time=>byTime.has(time)?Number(byTime.get(time).temperature):null),observations:buckets.map(time=>byTime.get(time)),spanGaps:false,borderColor:['#386d50','#b39453','#779da0','#9b5f91'][i%4],tension:0};});
  $('#trendStatus').textContent=d.rows.length?`${d.from} to ${d.to} · hourly averages from ${d.rows.reduce((sum,r)=>sum+Number(r.samples),0)} samples · Asia/Manila`:'No readings match these dates and filters.';
  charts.push(new Chart($('#temperatureChart'),{type:'line',data:{labels:buckets,datasets},options:{responsive:true,maintainAspectRatio:false,plugins:{tooltip:{callbacks:{afterLabel:context=>{const r=context.dataset.observations[context.dataIndex];return r?`Min ${r.minimum}°C · Max ${r.maximum}°C · ${r.samples} samples`:'';}}}},scales:{y:{title:{display:true,text:'°C'}}}}}));
 }catch(e){if(version===requestVersion&&seq===tableRequest)$('#trendStatus').textContent=e.message;}
}
function moduleShell(){const c=config[moduleName];$('#workspace').innerHTML=titleBlock(user.role==='guest'&&moduleName==='reservations'?'My reservations':c.title,c.subtitle,`${moduleName==='notifications'?'<button class="btn btn-outline-secondary" id="markRead">Mark all read</button>':''}${c.add&&canWrite(moduleName)?`<button class="btn btn-primary" data-new="${moduleName}"><i class="bi bi-plus-lg me-2"></i>${E(c.add)}</button>`:''}<button class="btn btn-light" id="refreshButton" aria-label="Refresh"><i class="bi bi-arrow-clockwise"></i></button>`)+(moduleName==='facilities'?'<section id="facilityGallery" class="facility-gallery" aria-label="Rooms and cottages"></section>':'')+(moduleName==='devices'?'<div class="device-grid" id="deviceCards"></div>':'')+(moduleName==='readings'?'<section class="panel mb-4"><div class="panel-head"><h2>Temperature trend</h2><span class="text-muted small">Hourly averages | selected dates | all matching samples</span></div><div id="trendStatus" class="px-4 small" role="status"></div><div class="panel-body chart-box"><canvas id="temperatureChart" aria-label="Temperature history" role="img"></canvas></div></section>':'')+`<section class="panel"><form class="toolbar" id="filterForm"><div class="search-wrap"><label for="search">Search records</label><input class="form-control" name="search" id="search" placeholder="Search ${E(c.title.toLowerCase())}…"></div>${c.statuses?`<div><label for="statusFilter">Status</label><select id="statusFilter" name="status" class="form-select"><option value="">All statuses</option>${c.statuses.map(s=>`<option value="${s}">${R360.label(s)}</option>`).join('')}</select></div>`:''}${c.archive&&user.role!=='guest'?'<div><label for="archiveFilter">Records</label><select id="archiveFilter" name="archived" class="form-select"><option value="0">Active records</option><option value="1">Archived records</option></select></div>':''}${['reservations','payments','cash_requests','readings','audit'].includes(moduleName)?'<div><label for="from">From</label><input class="form-control" type="date" name="from" id="from"></div><div><label for="to">To</label><input class="form-control" type="date" name="to" id="to"></div>':''}<div><label for="perPage">Per page</label><select id="perPage" class="form-select" name="per_page"><option>10</option><option>25</option><option>50</option></select></div><input type="hidden" name="sort" value="${moduleName==='readings'?'received_at':'created_at'}"><input type="hidden" name="direction" value="desc"><button class="btn btn-outline-secondary" type="submit">Apply</button></form><div id="tableArea"></div><div class="table-footer"><span id="recordCount"></span><div class="d-flex align-items-center gap-2"><button class="btn btn-light" id="prevPage" aria-label="Previous page"><i class="bi bi-chevron-left"></i></button><span id="pageCount"></span><button class="btn btn-light" id="nextPage" aria-label="Next page"><i class="bi bi-chevron-right"></i></button></div></div></section>`;
 if(moduleName==='payments')$('#workspace .mobile-toolbar').insertAdjacentHTML('afterbegin','<a class="btn btn-outline-secondary" href="#cash_requests">Cash payment slips</a>');
 const filter=$('#filterForm');
 if(moduleName==='reservations')filter.insertAdjacentHTML('afterbegin','<div><label for="operationFilter">Work queue</label><select class="form-select" name="operation" id="operationFilter"><option value="">All reservations</option><option value="arrivals">Arrivals today</option><option value="departures">Departures today</option><option value="overdue">Overdue check-outs</option><option value="outstanding">Outstanding balances</option></select></div>');
 for(const [key,value] of routeFilters){if(filter.elements[key])filter.elements[key].value=value;}
 if(moduleName==='readings'){filter.elements.from.value=manilaDate(-6);filter.elements.to.value=manilaDate();}
 $('#filterForm').addEventListener('submit',ev=>{ev.preventDefault();page=1;loadTable().catch(R360.error);});let timer;$('#search').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{if($('#filterForm')!==filter)return;page=1;loadTable().catch(R360.error);},350);});$('#filterForm').querySelectorAll('select').forEach(s=>s.addEventListener('change',()=>{page=1;loadTable().catch(R360.error);}));
 $('#prevPage').onclick=()=>{page--;loadTable().catch(R360.error);};$('#nextPage').onclick=()=>{page++;loadTable().catch(R360.error);};$('#refreshButton').onclick=()=>loadTable().catch(R360.error);$('#markRead')?.addEventListener('click',async()=>{try{await R360.api('notifications-read','POST',{});await loadTable();updateNotificationCount(0);}catch(e){R360.error(e);}});bindNew();
}
let tableRequest=0;
async function loadTable(version=requestVersion){const seq=++tableRequest;const currentModule=moduleName;const q=Object.fromEntries(new FormData($('#filterForm')));const d=await R360.api('records','GET',null,{module:currentModule,page,...q});if(version!==requestVersion||seq!==tableRequest)return;rows=d.rows;page=d.page;if(moduleName==='facilities')$('#facilityGallery').innerHTML=facilityCards(rows);$('#tableArea').innerHTML=tableHtml(rows,config[moduleName].columns,true,true);$('#recordCount').textContent=`${d.total} record${d.total===1?'':'s'} · showing ${rows.length}`;$('#pageCount').textContent=`${d.page} / ${d.pages}`;$('#prevPage').disabled=page<=1;$('#nextPage').disabled=page>=d.pages;$('#tableArea').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>recordAction(b.dataset).catch(R360.error));$('#tableArea').querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{const form=$('#filterForm');form.elements.direction.value=form.elements.sort.value===b.dataset.sort&&form.elements.direction.value==='asc'?'desc':'asc';form.elements.sort.value=b.dataset.sort;loadTable().catch(R360.error);});
 if(moduleName==='devices')$('#deviceCards').innerHTML=deviceCards(rows);
 if(moduleName==='readings')await loadTrend(q,version,seq);
}
function bindNew(){document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>openForm(b.dataset.new).catch(R360.error));}
