function formField(name,label,type='text',value='',options=[],required=true,extra=''){const attr=`id="field-${name}" name="${name}" ${required?'required':''} ${extra}`;let input=type==='select'?`<select class="form-select" ${attr}>${required?'':'<option value="">Unassigned</option>'}${options.map(o=>`<option value="${E(o.value)}" ${String(value)===String(o.value)?'selected':''}>${E(o.label)}</option>`).join('')}</select>`:type==='textarea'?`<textarea class="form-control" rows="3" ${attr}>${E(value)}</textarea>`:`<input class="form-control" type="${type}" value="${E(value)}" ${attr}>`;return `<div class="${type==='textarea'?'col-12':'col-md-6'}"><label for="field-${name}" class="form-label">${E(label)}${required?' *':''}</label>${input}<div class="invalid-feedback" data-error="${name}"></div></div>`;}
const opts=values=>values.map(v=>({value:v,label:R360.label(v)}));
const lookup=(key,filter=()=>true)=>(lookups[key]||[]).filter(filter).map(x=>({value:x.id,label:x.name}));
