 if(m==='cash_requests')return newCashSlip(prefill);
 lookups=await R360.api('lookups');const r=id?await R360.api('records','GET',null,{module:m,id,archived:$('#archiveFilter')?.value||0}):prefill;
 let fields='';const f=(name,label,type='text',options=[],required=true,extra='',fallback='')=>fields+=formField(name,label,type,r[name]??fallback,options,required,extra);
 if(m==='reservations'){
  if(user.role!=='guest')f('guest_id','Guest','select',lookup('guests'));f('arrival','Arrival','date',[],true,'');f('departure','Departure','date');f('guests_count','Number of guests','number',[],true,'min="1" max="1000"',1);f('facility_id','Room or cottage','select',lookup('facilities',x=>x.type!=='facility'));f('notes','Notes','textarea',[],false,'maxlength="1000"');
 }else if(m==='guests'){f('name','Full name','text',[],true,'maxlength="100"');f('email','Email','email',[],true,'maxlength="190"');f('phone','Contact number','tel',[],true,'maxlength="40"');f('address','Address','textarea',[],false,'maxlength="255"');}
 else if(m==='facilities'){f('name','Facility name','text',[],true,'maxlength="100"');f('type','Type','select',opts(['room','cottage','facility']));f('capacity','Capacity','number',[],true,'min="1" max="1000"',2);f('nightly_rate','Nightly rate (PHP)','number',[],true,'min="0" step="0.01"',0);f('status','Availability','select',opts(['available','maintenance']));f('image_path','Image path (assets/img)','text',[],false,'maxlength="255" placeholder="assets/img/room-photo.jpg"');f('description','Inclusions / details','textarea',[],false,'maxlength="3000" placeholder="Use Room Inclusions:, Details:, and Highlight: headings; add each item on a new line."');}
 else if(m==='payments'){f('reservation_id','Reservation','select',lookup('reservations'));f('amount','Amount (PHP)','number',[],true,'min="0.01" step="0.01"');f('method','Payment method','select',opts(['cash']));f('reference','Receipt / transaction reference','text',[],false,'maxlength="100"');f('notes','Notes','textarea',[],false,'maxlength="500"');}
